const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args && typeof source.args === 'object' ? source.args : {};
const tool = String(source.tool || args.tool || '').trim();
const text = String(args.instruction || args.text || args.prompt || source.text || source.rawText || '').trim();
const urlFromArgs = String(args.url || args.link || args.sourceUrl || args.source_url || source.url || '').trim();

function extractFirstUrl(value) {
  const match = String(value || '').match(/https?:\/\/[^\s<>\]\)"']+/i);
  return match ? match[0].replace(/[),.;!?]+$/, '') : '';
}

const url = urlFromArgs || extractFirstUrl(text) || extractFirstUrl(source.rawText || '');
const endpointMap = {
  'read_url': '/mia/web/read-url',
  'web.read_url': '/mia/web/read-url',
  'summarize_url': '/mia/web/summarize-url',
  'web.summarize_url': '/mia/web/summarize-url',
  'ask_url': '/mia/web/ask-url',
  'web.ask_url': '/mia/web/ask-url',
};
const endpointPath = endpointMap[tool] || '';
const fetchStrategy = String(args.fetchStrategy || args.fetch_strategy || source.fetchStrategy || source.fetch_strategy || 'auto').trim() || 'auto';
const maxChars = Number(args.maxChars || args.max_chars || 0) || 0;

if (!endpointPath) {
  return [{ json: { ok: false, error: `Unsupported web tool: ${tool}`, tool, url, requestId: String(source.requestId || '').trim(), originChatId: String(source.originChatId || source.chatId || '').trim(), deliveryMode: String(source.deliveryMode || 'return').trim() || 'return' } }];
}

return [{
  json: {
    ok: true,
    tool,
    endpointPath,
    url,
    instruction: text,
    text,
    prompt: text,
    maxChars,
    fetchStrategy,
    responseMode: String(args.responseMode || 'text').trim() || 'text',
    coreBaseUrl: String($env.MIA_CORE_URL || 'http://mia-core:8000').replace(/\/$/, ''),
    requestId: String(source.requestId || '').trim(),
    originChatId: String(source.originChatId || source.chatId || '').trim(),
    deliveryMode: String(source.deliveryMode || 'return').trim() || 'return',
  }
}];

const source = $('Normalize Web Input').item.json || {};
const output = $json || {};
const text = String(output.text || output.summary || output.result?.text || output.result?.summary || output.result?.answer || '').trim() || 'Mia đã xử lý xong link này.';
const warnings = Array.isArray(output.warnings) ? output.warnings : Array.isArray(output.result?.warnings) ? output.result.warnings : [];
return [{
  json: {
    ok: output.ok !== false,
    tool: output.tool || source.tool || '',
    url: output.url || source.url || '',
    text,
    result: output.data || output.result || output,
    warnings,
    trace: output.trace || output.result?.trace || {},
    requestId: source.requestId || '',
    originChatId: source.originChatId || '',
    deliveryMode: source.deliveryMode || 'return',
    fetchStrategy: output.fetchStrategy || output.fetch_strategy || source.fetchStrategy || source.fetch_strategy || 'auto',
  }
}];

const source = $('Normalize Web Input').item.json || {};
return [{
  json: {
    ok: false,
    error: source.endpointPath ? 'URL not found.' : `Unsupported web tool: ${source.tool || ''}`,
    tool: source.tool || '',
    url: source.url || '',
    requestId: source.requestId || '',
    originChatId: source.originChatId || '',
    deliveryMode: source.deliveryMode || 'return',
  }
}];
